import{_ as a,c as t,o as i,ae as o}from"./chunks/framework.DEXG3EuZ.js";const h=JSON.parse('{"title":"项目架构","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md","lastUpdated":1792605191000}'),r={name:"guide/architecture.md"};function s(l,e,c,d,n,p){return i(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="项目架构" tabindex="-1">项目架构 <a class="header-anchor" href="#项目架构" aria-label="Permalink to &quot;项目架构&quot;">​</a></h1><p>v2 的目标是让目录本身表达边界，让开发者和 Coding Agent 不需要猜测代码应该放在哪里。</p><h2 id="分层" tabindex="-1">分层 <a class="header-anchor" href="#分层" aria-label="Permalink to &quot;分层&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>views -&gt; components / composables -&gt; api modules / services -&gt; transport / types</span></span>
<span class="line"><span>main  -&gt; plugins / router / store</span></span>
<span class="line"><span>build -&gt; Vite plugins</span></span></code></pre></div><ul><li><code>src/api/client.ts</code> 只处理 Axios、拦截器、解包和 <code>ApiError</code>。</li><li><code>src/api/modules</code> 按业务域声明接口，不包含 Toast、Router 或组件逻辑。</li><li><code>src/services</code> 放框架无关的 Provider、协议解析器和 Adapter。</li><li><code>src/composables</code> 负责 Vue 响应式与生命周期编排。</li><li><code>src/store</code> 只保存 Client State；Server State 交给 TanStack Query。</li><li><code>src/views</code> 是路由级组合层，非首页页面均懒加载。</li></ul><h2 id="路由决策" tabindex="-1">路由决策 <a class="header-anchor" href="#路由决策" aria-label="Permalink to &quot;路由决策&quot;">​</a></h2><p>项目继续使用显式手写 Router。当前页面规模下，显式 <code>RouteRecordRaw</code> 更容易审查权限、Layout、title、KeepAlive 和 bundle 边界。旧 <code>vite-plugin-pages</code> 没有恢复；若未来页面达到需要文件约定的规模，应优先评估 <code>unplugin-vue-router</code>，并把 typed routes、meta、layout 和迁移测试作为完整方案引入。</p><h2 id="构建" tabindex="-1">构建 <a class="header-anchor" href="#构建" aria-label="Permalink to &quot;构建&quot;">​</a></h2><p>Vite 8 使用 Rolldown。<code>VITE_UI_FRAMEWORK</code> 选择唯一 UI resolver 与 demo alias；AI Chat、Query 示例和非核心页面走动态 import。SVG Sprite 始终可用；Sharp/SVGO、PWA、Gzip 和 bundle report 都由环境变量控制。</p><h2 id="受保护的约束" tabindex="-1">受保护的约束 <a class="header-anchor" href="#受保护的约束" aria-label="Permalink to &quot;受保护的约束&quot;">​</a></h2><ul><li>请求层不依赖 UI 或 Router。</li><li>Service Worker 不默认缓存 API。</li><li>三套 UI 不同时进入 production graph。</li><li>AI/Markdown 输出必须净化。</li><li>pnpm 是唯一包管理器。</li></ul>`,11)])])}const m=a(r,[["render",s]]);export{h as __pageData,m as default};
